css:
.tcl-order-parse{width:100%;max-width:360px;box-sizing:border-box;background:#05080d;border:1px solid #17222d;padding:6px 7px 7px;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:9.5px;line-height:1.3;color:#a9bccb;font-variant-numeric:tabular-nums}
.tcl-order-parse-hd{display:flex;justify-content:space-between;align-items:baseline;border-bottom:1px solid #17222d;padding-bottom:4px}
.tcl-order-parse-ttl{color:#e6eef4;font-size:8.5px;letter-spacing:.2em}
.tcl-order-parse-sub{color:#485e70;font-size:8px;letter-spacing:.08em}
.tcl-order-parse-cli{display:flex;align-items:center;gap:5px;padding:5px 0 5px}
.tcl-order-parse-ps{color:#3ddc97;flex:none}
.tcl-order-parse-in{flex:1;min-width:0;background:transparent;border:0;outline:none;padding:0;color:#e6eef4;font:inherit;caret-color:#3ddc97}
.tcl-order-parse-in::placeholder{color:#33465a}
.tcl-order-parse-rail{display:grid;grid-template-columns:repeat(6,1fr);gap:3px;padding-bottom:6px}
.tcl-order-parse-sl{font-size:7.5px;letter-spacing:.06em;text-align:center;padding:2px 1px;border:1px solid #16212c;color:#3d5266;white-space:nowrap;overflow:hidden}
.tcl-order-parse-sl.tcl-order-parse-ok{color:#cfe4f2;border-color:#27455c;background:#0b1720}
.tcl-order-parse-sl.tcl-order-parse-cur{color:#3ddc97;border-color:#2c6b52}
.tcl-order-parse-sl.tcl-order-parse-bad{color:#ff5c6c;border-color:#5c2530;background:#1a0d11}
.tcl-order-parse-kv{display:grid;grid-template-columns:auto 1fr auto 1fr;column-gap:6px;row-gap:2px;border-top:1px solid #16212c;padding-top:5px}
.tcl-order-parse-k{color:#41576a;font-size:7.5px;letter-spacing:.09em;align-self:center;white-space:nowrap}
.tcl-order-parse-v{color:#d8e6f0;text-align:right;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tcl-order-parse-v.tcl-order-parse-up{color:#3ddc97}
.tcl-order-parse-v.tcl-order-parse-dn{color:#ff5c6c}
.tcl-order-parse-v.tcl-order-parse-wa{color:#ffbe4d}
.tcl-order-parse-msg{margin-top:5px;border-top:1px solid #16212c;padding-top:4px;font-size:8.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#485e70}
.tcl-order-parse-msg.tcl-order-parse-good{color:#3ddc97}
.tcl-order-parse-msg.tcl-order-parse-warn{color:#ffbe4d}
.tcl-order-parse-msg.tcl-order-parse-err{color:#ff5c6c}
.tcl-order-parse-wrap{margin-top:4px;max-height:46px;overflow-y:auto;border-top:1px solid #16212c;padding-top:3px;scrollbar-width:thin;scrollbar-color:#22323f transparent}
.tcl-order-parse-wrap::-webkit-scrollbar{width:3px}
.tcl-order-parse-wrap::-webkit-scrollbar-thumb{background:#22323f}
.tcl-order-parse-wrap::-webkit-scrollbar-track{background:transparent}
.tcl-order-parse-w{display:grid;grid-template-columns:50px 10px 1fr 42px 48px;column-gap:5px;font-size:8.5px;color:#71889b;padding:1px 0}
.tcl-order-parse-w>span:nth-child(3),.tcl-order-parse-w>span:nth-child(4){text-align:right}
.tcl-order-parse-q{color:#9fb5c6}
.tcl-order-parse-buy{color:#3ddc97}
.tcl-order-parse-sel{color:#ff5c6c}
.tcl-order-parse-st{color:#5f7a8e;text-align:right;letter-spacing:.05em}
.tcl-order-parse-new{animation:tcl-order-parse-flash .7s ease-out}
@keyframes tcl-order-parse-flash{0%{background:rgba(61,220,151,.28);color:#eafff4}100%{background:transparent}}
@media (prefers-reduced-motion:reduce){.tcl-order-parse-new{animation:none}}

js:
var reduce = window.matchMedia('(prefers-reduced-motion:reduce)').matches;
var inp = root.querySelector('.tcl-order-parse-in');
var rail = Array.prototype.slice.call(root.querySelectorAll('.tcl-order-parse-sl'));
var msg = root.querySelector('.tcl-order-parse-msg');
var list = root.querySelector('.tcl-order-parse-list');
var sub = root.querySelector('.tcl-order-parse-sub');
var fields = {};
Array.prototype.forEach.call(root.querySelectorAll('[data-f]'), function (el) { fields[el.getAttribute('data-f')] = el; });
var LBL = ['SIDE', 'QTY', 'SYM', 'TYPE', 'PX', 'TIF'];
var SYMS = {
  AAPL: { px: 214.30, adv: 54200000 }, MSFT: { px: 402.05, adv: 21800000 },
  NVDA: { px: 118.62, adv: 289400000 }, SPY: { px: 546.18, adv: 68900000 },
  F: { px: 11.84, adv: 62100000 }, XOM: { px: 117.42, adv: 17300000 },
  TSLA: { px: 248.77, adv: 96500000 }
};
var SIDES = { B: 'BUY', BUY: 'BUY', S: 'SELL', SELL: 'SELL', SS: 'SSHRT', SHORT: 'SSHRT' };
var TYPES = { MKT: 0, LMT: 1, STP: 1, VWAP: 0, TWAP: 0, POV: 0 };
var TIFS = { DAY: 1, IOC: 1, GTC: 1, FOK: 1, OPG: 1, CLS: 1 };
var VENUES = ['ARCA', 'NSDQ', 'EDGX', 'BATS', 'IEX'];
var CAP = 30000000, FEEBP = 0.35, working = 2, held = false;
function num(n, d) {
  var s = Math.abs(n).toFixed(d === undefined ? 0 : d).split('.');
  s[0] = s[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return (n < 0 ? '-' : '') + s.join('.');
}
function say(t, cls) {
  if (held) return;
  msg.className = 'tcl-order-parse-msg' + (cls ? ' tcl-order-parse-' + cls : '');
  msg.textContent = t;
}
function parse(str) {
  var o = { slots: ['', '', '', '', '', ''], ok: false, err: '', bad: -1 };
  var t = str.toUpperCase().trim().split(/\s+/).filter(function (x) { return x.length; });
  if (!t.length) { o.err = 'grammar: <side> <qty> <sym> <type> [px] [tif]'; return o; }
  if (!SIDES[t[0]]) { o.err = 'SIDE must be B | S | SS'; o.bad = 0; return o; }
  o.side = SIDES[t[0]]; o.slots[0] = o.side;
  if (t.length < 2) { o.err = 'awaiting QTY'; return o; }
  var q = parseFloat(t[1].replace(/,/g, ''));
  if (!isFinite(q) || q <= 0 || q % 1 !== 0) { o.err = 'QTY must be a whole number of shares'; o.bad = 1; return o; }
  o.qty = q; o.slots[1] = num(q);
  if (t.length < 3) { o.err = 'awaiting SYMBOL'; return o; }
  if (!SYMS[t[2]]) { o.err = 'no security matching ' + t[2]; o.bad = 2; return o; }
  o.sym = t[2]; o.slots[2] = t[2];
  if (t.length < 4) { o.err = 'awaiting TYPE'; return o; }
  if (!(t[3] in TYPES)) { o.err = 'TYPE must be MKT|LMT|STP|VWAP|TWAP|POV'; o.bad = 3; return o; }
  o.typ = t[3]; o.slots[3] = t[3];
  var i = 4;
  if (TYPES[t[3]]) {
    if (t.length < 5) { o.err = t[3] + ' requires a limit price'; return o; }
    var p = parseFloat(t[4]);
    if (!isFinite(p) || p <= 0) { o.err = 'PRICE must be numeric'; o.bad = 4; return o; }
    o.px = p; o.slots[4] = p.toFixed(2); i = 5;
  } else { o.slots[4] = '—'; }
  if (t.length <= i) { o.err = 'awaiting TIF'; return o; }
  if (!TIFS[t[i]]) { o.err = 'TIF must be DAY|IOC|GTC|FOK|OPG|CLS'; o.bad = i; return o; }
  o.tif = t[i]; o.slots[5] = t[i];
  if (t.length > i + 1) { o.err = 'unexpected token ' + t[i + 1]; o.bad = i + 1; return o; }
  o.ok = true; return o;
}
var cur = null;
function render() {
  var o = parse(inp.value); cur = o;
  var first = -1;
  for (var i = 0; i < 6; i++) {
    var c = 'tcl-order-parse-sl';
    if (o.slots[i]) { c += ' tcl-order-parse-ok'; }
    else if (first < 0) { first = i; c += ' tcl-order-parse-cur'; }
    if (o.bad === i) { c = 'tcl-order-parse-sl tcl-order-parse-bad'; }
    rail[i].className = c;
    rail[i].textContent = o.slots[i] || LBL[i];
  }
  if (o.sym) {
    var s = SYMS[o.sym];
    fields.last.textContent = s.px.toFixed(2) + (s.dir === 1 ? ' ▲' : s.dir === -1 ? ' ▼' : '');
    fields.last.className = 'tcl-order-parse-v ' + (s.dir === 1 ? 'tcl-order-parse-up' : s.dir === -1 ? 'tcl-order-parse-dn' : '');
  } else { fields.last.textContent = '—'; fields.last.className = 'tcl-order-parse-v'; }
  if (!o.ok) {
    fields.not.textContent = '—'; fields.adv.textContent = '—';
    fields.vs.textContent = '—'; fields.vs.className = 'tcl-order-parse-v';
    fields.fee.textContent = '—'; fields.util.textContent = '—';
    fields.util.className = 'tcl-order-parse-v';
    say((o.bad >= 0 ? '✖ ' : '') + o.err, o.bad >= 0 ? 'err' : '');
    return;
  }
  var ref = SYMS[o.sym].px, mark = o.px || ref;
  var notional = o.qty * mark;
  var advp = o.qty / SYMS[o.sym].adv * 100;
  var fee = notional * FEEBP / 10000;
  var util = notional / CAP * 100;
  var vs = o.px ? (o.px - ref) / ref * 10000 : 0;
  fields.not.textContent = num(notional);
  fields.adv.textContent = advp.toFixed(3) + '%';
  fields.fee.textContent = num(fee, 2);
  fields.vs.textContent = o.px ? (vs >= 0 ? '+' : '') + vs.toFixed(1) + 'bp' : 'n/a';
  fields.vs.className = 'tcl-order-parse-v' + (!o.px ? '' : Math.abs(vs) > 200 ? ' tcl-order-parse-wa' : vs >= 0 ? ' tcl-order-parse-up' : ' tcl-order-parse-dn');
  fields.util.textContent = util.toFixed(1) + '%';
  fields.util.className = 'tcl-order-parse-v' + (util > 100 ? ' tcl-order-parse-dn' : util > 80 ? ' tcl-order-parse-wa' : '');
  if (util > 100) {
    say('✖ RISK BLOCK · ' + num(notional / 1e6, 2) + 'MM over 30.0MM single-order cap', 'err');
  } else if (o.px && Math.abs(vs) > 200) {
    say('⚠ limit ' + Math.abs(vs).toFixed(0) + 'bp ' + (vs > 0 ? 'through' : 'behind') + ' last · ⏎ to stage anyway', 'warn');
  } else {
    say('READY · ⏎ stage ' + o.side + ' ' + num(o.qty) + ' ' + o.sym + ' · ' + num(notional / 1e6, 2) + 'MM', 'good');
  }
}
function hex4() {
  var s = '', d = '0123456789ABCDEF';
  for (var i = 0; i < 4; i++) { s += d[Math.floor(Math.random() * 16)]; }
  return s;
}
function stage(o) {
  var mark = o.px || SYMS[o.sym].px;
  var id = 'ORD-' + hex4();
  var ven = VENUES[Math.floor(Math.random() * VENUES.length)];
  var row = document.createElement('div');
  row.className = 'tcl-order-parse-w' + (reduce ? '' : ' tcl-order-parse-new');
  var cells = [id, o.side === 'BUY' ? 'B' : 'S', num(o.qty) + ' ' + o.sym, mark.toFixed(2),
    o.tif === 'IOC' || o.tif === 'FOK' ? 'FILLED' : 'WORKING'];
  var cls = ['', o.side === 'BUY' ? 'tcl-order-parse-buy' : 'tcl-order-parse-sel', 'tcl-order-parse-q', 'tcl-order-parse-q', 'tcl-order-parse-st'];
  for (var i = 0; i < 5; i++) {
    var sp = document.createElement('span');
    if (cls[i]) sp.className = cls[i];
    sp.textContent = cells[i];
    row.appendChild(sp);
  }
  list.insertBefore(row, list.firstChild);
  while (list.children.length > 8) { list.removeChild(list.lastChild); }
  if (cells[4] === 'WORKING') working++;
  sub.textContent = 'DESK-04 · ' + working + ' WORKING';
  held = true;
  msg.className = 'tcl-order-parse-msg tcl-order-parse-good';
  msg.textContent = '✓ ACK ' + id + ' · ROUTED ' + ven + ' · ' + cells[4];
  inp.value = '';
  inp.setAttribute('placeholder', 'S 5000 MSFT LMT 402.00 IOC');
}
inp.addEventListener('input', function () { held = false; render(); });
inp.addEventListener('keydown', function (e) {
  if (e.key !== 'Enter') return;
  e.preventDefault();
  held = false;
  var o = cur || parse(inp.value);
  if (!o.ok) {
    say('✖ not staged · ' + o.err, 'err');
    return;
  }
  var notional = o.qty * (o.px || SYMS[o.sym].px);
  if (notional / CAP * 100 > 100) {
    say('✖ REJECTED BY PRE-TRADE RISK · notional cap', 'err');
    return;
  }
  stage(o);
});
render();
if (!reduce) {
  var keys = Object.keys(SYMS);
  var tick = setInterval(function () {
    if (!root.isConnected) { clearInterval(tick); return; }
    var k = keys[Math.floor(Math.random() * keys.length)];
    var s = SYMS[k], up = Math.random() < 0.5 ? -1 : 1;
    s.px = Math.round((s.px + up * 0.01) * 100) / 100;
    s.dir = up;
    if (cur && cur.sym === k) render();
  }, 1700);
}

var out = root.querySelector('.tcl-repl-query-out');
var inp = root.querySelector('.tcl-repl-query-in');
var hist = [], hix = 0;
function pad(s, n) { s = String(s); while (s.length < n) { s += ' '; } return s; }
function lpad(s, n) { s = String(s); while (s.length < n) { s = ' ' + s; } return s; }
function num(n, d) {
  var s = Math.abs(n).toFixed(d === undefined ? 0 : d).split('.');
  s[0] = s[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return (n < 0 ? '-' : '') + s.join('.');
}
function sgn(n, d) { return (n >= 0 ? '+' : '-') + num(Math.abs(n), d); }
function line(txt, cls) {
  var d = document.createElement('div');
  d.className = 'tcl-repl-query-l' + (cls ? ' tcl-repl-query-' + cls : '');
  d.textContent = txt;
  out.appendChild(d);
}
var BOOK = {
  AAPL: { n: 'APPLE INC', b: 214.28, a: 214.31, l: 214.30, bs: '1.2k', as: '0.9k', adv: '54.2M', isin: 'US0378331005', cusip: '037833100', x: 'NASDAQ GS', cap: '3.25T', beta: 1.09 },
  NVDA: { n: 'NVIDIA CORP', b: 118.61, a: 118.63, l: 118.62, bs: '2.4k', as: '1.9k', adv: '289.4M', isin: 'US67066G1040', cusip: '67066G104', x: 'NASDAQ GS', cap: '2.91T', beta: 1.72 },
  MSFT: { n: 'MICROSOFT CORP', b: 402.02, a: 402.09, l: 402.05, bs: '0.6k', as: '0.7k', adv: '21.8M', isin: 'US5949181045', cusip: '594918104', x: 'NASDAQ GS', cap: '2.99T', beta: 0.92 },
  XOM: { n: 'EXXON MOBIL', b: 117.40, a: 117.44, l: 117.42, bs: '1.1k', as: '1.4k', adv: '17.3M', isin: 'US30231G1022', cusip: '30231G102', x: 'NYSE', cap: '516.4B', beta: 0.81 }
};
var POS = [
  { s: 'AAPL', q: 120000, avg: 208.44, mk: 214.30 },
  { s: 'NVDA', q: -45000, avg: 121.05, mk: 118.62 },
  { s: 'MSFT', q: 18500, avg: 409.60, mk: 402.05 }
];
var CURVE = [
  { t: '2Y', y: 4.312, c: -1.2, dv: 192 },
  { t: '5Y', y: 3.976, c: -0.8, dv: 455 },
  { t: '10Y', y: 4.084, c: 0.4, dv: 830 },
  { t: '30Y', y: 4.312, c: 1.1, dv: 1905 }
];
function kv(k, v, sign, tail) {
  var d = document.createElement('div');
  d.className = 'tcl-repl-query-l';
  var a = document.createElement('span');
  a.className = 'tcl-repl-query-hdr';
  a.textContent = pad(k, 10);
  var b = document.createElement('span');
  b.className = sign >= 0 ? 'tcl-repl-query-pos' : 'tcl-repl-query-neg';
  b.textContent = lpad(v, 16);
  d.appendChild(a); d.appendChild(b);
  if (tail) {
    var c = document.createElement('span');
    c.className = 'tcl-repl-query-dim';
    c.textContent = tail;
    d.appendChild(c);
  }
  out.appendChild(d);
}
function upnl(p) { return p.q * (p.mk - p.avg); }
function gmv() { var g = 0; for (var i = 0; i < POS.length; i++) { g += Math.abs(POS[i].q) * POS[i].mk; } return g; }
function nmv() { var g = 0; for (var i = 0; i < POS.length; i++) { g += POS[i].q * POS[i].mk; } return g; }
var CMDS = {
  px: function (a) {
    if (!a) { line('?? px requires a ticker', 'bad'); return; }
    var s = BOOK[a];
    if (!s) { line('?? no security matching ' + a, 'bad'); return; }
    var mid = (s.b + s.a) / 2, sp = s.a - s.b;
    line(pad(a + ' US · ' + s.n, 30) + lpad('LAST ' + s.l.toFixed(2), 13), 'key');
    line('BID ' + s.b.toFixed(2) + ' x' + pad(s.bs, 6) + 'ASK ' + s.a.toFixed(2) + ' x' + s.as);
    line('SPRD ' + sp.toFixed(2) + '  ' + (sp / mid * 10000).toFixed(1) + 'bp' + lpad('ADV ' + s.adv, 22), 'dim');
  },
  pos: function () {
    line(pad('SYM', 6) + lpad('QTY', 9) + lpad('AVG', 9) + lpad('MARK', 8) + lpad('UPNL', 11), 'hdr');
    var net = 0;
    for (var i = 0; i < POS.length; i++) {
      var p = POS[i], u = upnl(p);
      net += u;
      var d = document.createElement('div');
      d.className = 'tcl-repl-query-l';
      var a = document.createElement('span');
      a.textContent = pad(p.s, 6) + lpad(num(p.q), 9) + lpad(p.avg.toFixed(2), 9) + lpad(p.mk.toFixed(2), 8);
      var b = document.createElement('span');
      b.className = u >= 0 ? 'tcl-repl-query-pos' : 'tcl-repl-query-neg';
      b.textContent = lpad(sgn(u), 11);
      d.appendChild(a); d.appendChild(b); out.appendChild(d);
    }
    line(lpad('NET UNREALISED', 32) + lpad(sgn(net), 11), net >= 0 ? 'pos' : 'neg');
  },
  pnl: function () {
    var u = 0;
    for (var i = 0; i < POS.length; i++) { u += upnl(POS[i]); }
    var real = 48210, tot = real + u, g = gmv(), n = nmv();
    line('INTRADAY P&L · DESK-04 · T+0', 'hdr');
    kv('REALISED', sgn(real), real);
    kv('UNREALISED', sgn(u), u);
    kv('TOTAL', sgn(tot), tot, lpad(sgn(tot / g * 10000, 1) + 'bp', 12));
    line(pad('GMV', 10) + lpad(num(g), 16) + lpad('NMV ' + sgn(n), 18), 'dim');
    line(pad('SHARPE 1.84', 14) + lpad('HIT 61.4%', 13) + lpad('MAXDD -2.1%', 14), 'dim');
  },
  desc: function (a) {
    if (!a) { line('?? desc requires a ticker', 'bad'); return; }
    var s = BOOK[a];
    if (!s) { line('?? no security matching ' + a, 'bad'); return; }
    line(a + ' US EQUITY · ' + s.n, 'key');
    line(pad('ISIN  ' + s.isin, 24) + 'CUSIP ' + s.cusip, 'dim');
    line(pad('EXCH  ' + s.x, 24) + 'CCY USD  LOT 1', 'dim');
    line(pad('MKTCAP ' + s.cap, 24) + 'BETA ' + s.beta.toFixed(2) + '  ADV ' + s.adv, 'dim');
  },
  curve: function () {
    line(pad('TENOR', 8) + lpad('YLD', 7) + lpad('CHG', 7) + lpad('DV01/MM', 12), 'hdr');
    for (var i = 0; i < CURVE.length; i++) {
      var c = CURVE[i];
      line(pad(c.t, 8) + lpad(c.y.toFixed(3), 7) + lpad(sgn(c.c, 1), 7) + lpad(num(c.dv), 12));
    }
    var sp = (CURVE[2].y - CURVE[0].y) * 100;
    line(pad('2s10s', 8) + lpad(sgn(sp, 1) + 'bp', 7) + lpad('INVERTED', 19), 'neg');
  },
  help: function () {
    line('VERB       ARGUMENT   RETURNS', 'hdr');
    line('px         <TKR>      two-sided quote, spread bp');
    line('pos                   open positions, unrealised');
    line('pnl                   day P&L, GMV / NMV, ratios');
    line('desc       <TKR>      identifiers and static data');
    line('curve                 UST par curve and DV01');
    line('clear                 wipe scrollback', 'dim');
  },
  clear: function () { while (out.firstChild) { out.removeChild(out.firstChild); } }
};
function run(raw) {
  var s = raw.trim();
  if (!s) return;
  line('q> ' + s, 'dim');
  var parts = s.split(/\s+/);
  var verb = parts[0].toLowerCase();
  var arg = parts[1] ? parts[1].toUpperCase() : '';
  if (CMDS[verb]) { CMDS[verb](arg); }
  else { line("?? unknown verb '" + verb + "' — try help", 'bad'); }
  out.scrollTop = out.scrollHeight;
}
inp.addEventListener('keydown', function (e) {
  if (e.key === 'Enter') {
    e.preventDefault();
    var v = inp.value;
    if (v.trim()) { hist.push(v.trim()); }
    hix = hist.length;
    run(v);
    inp.value = '';
  } else if (e.key === 'ArrowUp') {
    e.preventDefault();
    if (hix > 0) { hix--; inp.value = hist[hix]; }
  } else if (e.key === 'ArrowDown') {
    e.preventDefault();
    if (hix < hist.length - 1) { hix++; inp.value = hist[hix]; }
    else { hix = hist.length; inp.value = ''; }
  }
});
line('OMS query console — 4 securities in scope', 'dim');
run('pos');
run('px NVDA');

