var inp = root.querySelector('.tcl-palette-fn-in');
var list = root.querySelector('.tcl-palette-fn-list');
var cnt = root.querySelector('.tcl-palette-fn-cnt');
var st = root.querySelector('.tcl-palette-fn-st');
var rows = Array.prototype.slice.call(root.querySelectorAll('.tcl-palette-fn-row'));
var sel = 0;
function paint(el, text, idx, from) {
  while (el.firstChild) { el.removeChild(el.firstChild); }
  for (var i = 0; i < text.length; i++) {
    var hit = idx.indexOf(from + i) >= 0;
    if (hit) {
      var b = document.createElement('span');
      b.className = 'tcl-palette-fn-hi';
      b.textContent = text.charAt(i);
      el.appendChild(b);
    } else {
      el.appendChild(document.createTextNode(text.charAt(i)));
    }
  }
}
function match(hay, q) {
  var idx = [], j = 0;
  for (var i = 0; i < hay.length && j < q.length; i++) {
    if (hay.charAt(i) === q.charAt(j)) { idx.push(i); j++; }
  }
  return j === q.length ? idx : null;
}
function visible() {
  return rows.filter(function (r) { return r.className.indexOf('tcl-palette-fn-hide') < 0; });
}
function mark() {
  var v = visible();
  if (sel >= v.length) sel = v.length - 1;
  if (sel < 0) sel = 0;
  for (var i = 0; i < rows.length; i++) {
    rows[i].className = rows[i].className.replace(' tcl-palette-fn-on', '');
  }
  if (!v.length) return;
  var el = v[sel];
  el.className += ' tcl-palette-fn-on';
  var top = el.offsetTop - list.offsetTop;
  if (top < list.scrollTop) { list.scrollTop = top; }
  else if (top + el.offsetHeight > list.scrollTop + list.clientHeight) {
    list.scrollTop = top + el.offsetHeight - list.clientHeight;
  }
}
function filter() {
  var q = inp.value.toLowerCase().replace(/\s+/g, '');
  var shown = 0;
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i];
    var mn = r.getAttribute('data-mn'), nm = r.getAttribute('data-nm');
    var hay = (mn + ' ' + nm).toLowerCase();
    var idx = q ? match(hay, q) : [];
    var mnEl = r.querySelector('.tcl-palette-fn-mn');
    var nmEl = r.querySelector('.tcl-palette-fn-nm');
    if (!idx) {
      r.className = 'tcl-palette-fn-row tcl-palette-fn-hide';
      continue;
    }
    r.className = 'tcl-palette-fn-row';
    shown++;
    paint(mnEl, mn, idx, 0);
    paint(nmEl, nm, idx, mn.length + 1);
  }
  cnt.textContent = rows.length + ' fn · ' + shown + ' shown';
  sel = 0;
  mark();
  if (!shown) {
    st.className = 'tcl-palette-fn-st tcl-palette-fn-no';
    st.textContent = 'no function matches';
  } else {
    st.className = 'tcl-palette-fn-st';
    st.textContent = '↑↓ move · ⏎ run';
  }
}
function launch() {
  var v = visible();
  if (!v.length) return;
  var r = v[sel];
  var ms = 7 + Math.floor(Math.random() * 9);
  inp.value = '';
  filter();
  st.className = 'tcl-palette-fn-st tcl-palette-fn-go';
  st.textContent = '▶ ' + r.getAttribute('data-mn') + ' <GO> · panel 2 · ' + ms + 'ms';
}
inp.addEventListener('input', filter);
inp.addEventListener('keydown', function (e) {
  if (e.key === 'ArrowDown') { e.preventDefault(); sel++; mark(); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); sel--; mark(); }
  else if (e.key === 'Enter') { e.preventDefault(); launch(); }
  else if (e.key === 'Escape') { e.preventDefault(); inp.value = ''; filter(); }
});
list.addEventListener('mousedown', function (e) {
  var r = e.target;
  while (r && r !== list && r.className.indexOf('tcl-palette-fn-row') < 0) { r = r.parentNode; }
  if (!r || r === list) return;
  e.preventDefault();
  sel = visible().indexOf(r);
  mark();
  launch();
});
filter();

