js:
var inp = root.querySelector('.tcl-sec-lookup-in');
var list = root.querySelector('.tcl-sec-lookup-list');
var sub = root.querySelector('.tcl-sec-lookup-sub');
var l1 = root.querySelector('.tcl-sec-lookup-l1');
var l2 = Array.prototype.slice.call(root.querySelectorAll('.tcl-sec-lookup-l2'));
var reduce = window.matchMedia('(prefers-reduced-motion:reduce)').matches;
var rows = Array.prototype.slice.call(root.querySelectorAll('.tcl-sec-lookup-row'));
var sel = 0;
function score(hay, q) {
  var idx = [], j = 0, run = 0, s = 0;
  for (var i = 0; i < hay.length && j < q.length; i++) {
    if (hay.charAt(i) === q.charAt(j)) {
      idx.push(i);
      run++;
      s += 6 + run * 4;
      if (i === 0) { s += 30; }
      else if (' -/.'.indexOf(hay.charAt(i - 1)) >= 0) { s += 12; }
      j++;
    } else { run = 0; }
  }
  if (j < q.length) return null;
  return { s: s - idx[0] * 0.6, idx: idx };
}
function paint(el, text, idx, from) {
  while (el.firstChild) { el.removeChild(el.firstChild); }
  for (var i = 0; i < text.length; i++) {
    if (idx.indexOf(from + i) >= 0) {
      var b = document.createElement('span');
      b.className = 'tcl-sec-lookup-hi';
      b.textContent = text.charAt(i);
      el.appendChild(b);
    } else { el.appendChild(document.createTextNode(text.charAt(i))); }
  }
}
function visible() {
  return rows.filter(function (r) { return r.className.indexOf('tcl-sec-lookup-hide') < 0; });
}
function mark() {
  var v = visible();
  if (sel >= v.length) sel = v.length - 1;
  if (sel < 0) sel = 0;
  for (var i = 0; i < rows.length; i++) {
    rows[i].className = rows[i].className.replace(' tcl-sec-lookup-on', '');
  }
  if (!v.length) return;
  var el = v[sel];
  el.className += ' tcl-sec-lookup-on';
  var top = el.offsetTop - list.offsetTop;
  if (top < list.scrollTop) { list.scrollTop = top; }
  else if (top + el.offsetHeight > list.scrollTop + list.clientHeight) {
    list.scrollTop = top + el.offsetHeight - list.clientHeight;
  }
}
function filter() {
  var q = inp.value.toLowerCase().replace(/\s+/g, ' ').trim();
  var scored = [];
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i];
    var t = r.getAttribute('data-t'), n = r.getAttribute('data-n'), isin = r.getAttribute('data-i');
    var tk = r.querySelector('.tcl-sec-lookup-tk'), nm = r.querySelector('.tcl-sec-lookup-nm');
    if (!q) {
      r.className = 'tcl-sec-lookup-row';
      tk.textContent = t; nm.textContent = n;
      scored.push({ r: r, s: -i });
      continue;
    }
    var a = score(t.toLowerCase(), q), b = score(n.toLowerCase(), q), c = score(isin.toLowerCase(), q);
    var best = null, where = 0;
    if (a) { best = a; where = 0; }
    if (b && (!best || b.s + 4 > best.s)) { best = b; where = 1; }
    if (c && (!best || c.s > best.s + 30)) { best = c; where = 2; }
    if (!best) { r.className = 'tcl-sec-lookup-row tcl-sec-lookup-hide'; continue; }
    r.className = 'tcl-sec-lookup-row';
    tk.textContent = t; nm.textContent = n;
    if (where === 0) { paint(tk, t, best.idx, 0); }
    else if (where === 1) { paint(nm, n, best.idx, 0); }
    scored.push({ r: r, s: best.s + (where === 0 ? 25 : where === 2 ? -10 : 0) });
  }
  scored.sort(function (x, y) { return y.s - x.s; });
  for (var k = 0; k < scored.length; k++) { list.appendChild(scored[k].r); }
  sub.textContent = scored.length ? scored.length + ' of ' + rows.length + ' match' : 'no match';
  sel = 0;
  mark();
}
function load() {
  var v = visible();
  if (!v.length) return;
  var r = v[sel];
  l1.textContent = r.getAttribute('data-t') + ' · ' + r.getAttribute('data-n');
  l2[0].firstChild.textContent = 'ISIN ' + r.getAttribute('data-i');
  l2[0].lastChild.textContent = 'CUSIP ' + r.getAttribute('data-u');
  l2[1].firstChild.textContent = r.getAttribute('data-x') + ' · ' + r.getAttribute('data-y');
  l2[1].lastChild.textContent = r.getAttribute('data-c') + ' · LAST ' + r.getAttribute('data-p');
  if (!reduce) {
    l1.className = 'tcl-sec-lookup-l1';
    void l1.offsetWidth;
    l1.className = 'tcl-sec-lookup-l1 tcl-sec-lookup-flash';
  }
}
inp.addEventListener('input', filter);
inp.addEventListener('keydown', function (e) {
  if (e.key === 'ArrowDown') { e.preventDefault(); sel++; mark(); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); sel--; mark(); }
  else if (e.key === 'Enter') { e.preventDefault(); load(); }
  else if (e.key === 'Escape') { e.preventDefault(); inp.value = ''; filter(); }
});
list.addEventListener('mousedown', function (e) {
  var r = e.target;
  while (r && r !== list && r.className.indexOf('tcl-sec-lookup-row') < 0) { r = r.parentNode; }
  if (!r || r === list) return;
  e.preventDefault();
  sel = visible().indexOf(r);
  mark();
  load();
});
filter();

