var reduce = window.matchMedia('(prefers-reduced-motion:reduce)').matches;
var inp = root.querySelector('.tcl-confirm-kill-in');
var typed = root.querySelector('.tcl-confirm-kill-typed');
var rest = root.querySelector('.tcl-confirm-kill-rest');
var msg = root.querySelector('.tcl-confirm-kill-msg');
var cd = root.querySelector('.tcl-confirm-kill-cd');
var fill = root.querySelector('.tcl-confirm-kill-fill');
var rows = Array.prototype.slice.call(root.querySelectorAll('.tcl-confirm-kill-row'));
var PHRASE = 'PULL ALL', TOTAL = 30, REJECT = 3;
var left = TOTAL, live = true, running = false;
function setMsg(t, cls) {
  msg.className = 'tcl-confirm-kill-msg' + (cls ? ' tcl-confirm-kill-' + cls : '');
  msg.textContent = t;
}
function ghost() {
  var v = inp.value.toUpperCase();
  var ok = 0;
  while (ok < v.length && ok < PHRASE.length && v.charAt(ok) === PHRASE.charAt(ok)) { ok++; }
  typed.textContent = PHRASE.slice(0, ok);
  rest.textContent = PHRASE.slice(ok);
  typed.className = 'tcl-confirm-kill-typed';
  if (v.length > ok) {
    typed.className = 'tcl-confirm-kill-typed tcl-confirm-kill-badp';
    setMsg('phrase mismatch at char ' + (ok + 1) + ' — clear and retype', 'warn');
    return false;
  }
  if (v === PHRASE) { setMsg('ARMED · ⏎ pulls 6 orders · esc aborts', 'armed'); return true; }
  setMsg('type the phrase to arm · esc aborts');
  return false;
}
function stop() {
  live = false;
  fill.style.width = '0%';
  fill.className = 'tcl-confirm-kill-fill';
  cd.textContent = 'R';
  inp.setAttribute('readonly', 'readonly');
}
function rearm() {
  for (var i = 0; i < rows.length; i++) {
    rows[i].className = 'tcl-confirm-kill-row';
    rows[i].querySelector('.tcl-confirm-kill-stt').textContent = 'WRK';
  }
  running = false;
  live = true;
  left = TOTAL;
  inp.removeAttribute('readonly');
  inp.value = '';
  fill.style.width = '100%';
  fill.className = 'tcl-confirm-kill-fill';
  cd.textContent = TOTAL + 's';
  ghost();
  arm();
}
function abort(why) {
  if (running) return;
  stop();
  setMsg(why + ' · 6 left working · R re-arms', 'warn');
  typed.textContent = '';
  rest.textContent = PHRASE;
}
function execute() {
  if (running) return;
  running = true;
  stop();
  setMsg('CXL-REQ sent · 6 orders', 'done');
  var i = 0;
  var step = function () {
    if (!root.isConnected) return;
    if (i >= rows.length) {
      setMsg('5 CXL 23,625,450 · 1 REJ 955,200 · R re-arms', 'done');
      return;
    }
    var r = rows[i], stt = r.querySelector('.tcl-confirm-kill-stt');
    if (i === REJECT) {
      r.className = 'tcl-confirm-kill-row tcl-confirm-kill-rej';
      stt.textContent = 'REJ';
    } else {
      r.className = 'tcl-confirm-kill-row tcl-confirm-kill-gone';
      stt.textContent = 'CXL';
    }
    i++;
    setTimeout(step, reduce ? 0 : 190);
  };
  step();
}
inp.addEventListener('input', function () { if (live) ghost(); });
inp.addEventListener('keydown', function (e) {
  if (!live && (e.key === 'r' || e.key === 'R')) { e.preventDefault(); rearm(); return; }
  if (e.key === 'Escape') { e.preventDefault(); if (live) abort('ABORTED'); return; }
  if (e.key === 'Enter') {
    e.preventDefault();
    if (!live) return;
    if (inp.value.toUpperCase() === PHRASE) { execute(); }
    else { setMsg('not armed — phrase must read PULL ALL', 'warn'); }
  }
});
function arm() {
  var tick = setInterval(function () {
    if (!root.isConnected) { clearInterval(tick); return; }
    if (!live) { clearInterval(tick); return; }
    left--;
    cd.textContent = left + 's';
    fill.style.width = (left / TOTAL * 100).toFixed(1) + '%';
    if (left <= 8) {
      fill.className = 'tcl-confirm-kill-fill tcl-confirm-kill-hot' + (reduce ? '' : ' tcl-confirm-kill-pulse');
    }
    if (left <= 0) { clearInterval(tick); abort('AUTO-ABORT · prompt expired'); }
  }, 1000);
}
ghost();
arm();

