var pill = root.querySelector('.tcl-hotkey-card-pill');
var last = root.querySelector('.tcl-hotkey-card-last');
var cnt = root.querySelector('.tcl-hotkey-card-cnt');
var body = root.querySelector('.tcl-hotkey-card-body');
var rows = Array.prototype.slice.call(root.querySelectorAll('.tcl-hotkey-card-row'));
var map = {}, fired = {}, nFired = 0, timer = null;
for (var i = 0; i < rows.length; i++) { map[rows[i].getAttribute('data-chord')] = rows[i]; }
var GLYPH = { ctrl: '⌃', alt: '⌥', shift: '⇧', meta: '⌘' };
function pretty(mods, code) {
  var s = '';
  for (var i = 0; i < mods.length; i++) { s += GLYPH[mods[i]]; }
  return s + code.replace(/^Key/, '').replace(/^Digit/, '').replace(/^Arrow/, '')
    .replace('Slash', '/').replace('Period', '.').replace('Comma', ',')
    .replace('Up', '↑').replace('Down', '↓').replace('Left', '←').replace('Right', '→');
}
root.addEventListener('focus', function () { pill.textContent = 'KEYS ARMED'; });
root.addEventListener('blur', function () { pill.textContent = 'CLICK TO ARM'; });
root.addEventListener('mousedown', function () { root.focus(); });
root.addEventListener('keydown', function (e) {
  if (e.key === 'Tab') return;
  var mods = [];
  if (e.ctrlKey) mods.push('ctrl');
  if (e.altKey) mods.push('alt');
  if (e.shiftKey) mods.push('shift');
  if (e.metaKey) mods.push('meta');
  var chord = mods.concat([e.code]).join('+');
  var row = map[chord];
  if (row || e.altKey || (e.shiftKey && e.code.indexOf('Arrow') === 0)) { e.preventDefault(); }
  if (!row) {
    if (!mods.length) return;
    last.className = 'tcl-hotkey-card-last tcl-hotkey-card-no';
    last.textContent = pretty(mods, e.code) + ' · no macro bound';
    return;
  }
  for (var i = 0; i < rows.length; i++) {
    rows[i].className = rows[i].className.replace(' tcl-hotkey-card-hit', '');
  }
  row.className += ' tcl-hotkey-card-hit';
  if (!fired[chord]) { fired[chord] = 1; nFired++; cnt.textContent = nFired + '/' + rows.length + ' fired'; }
  if (!row.className.match(/tcl-hotkey-card-used/)) { row.className += ' tcl-hotkey-card-used'; }
  last.className = 'tcl-hotkey-card-last tcl-hotkey-card-ok';
  last.textContent = row.querySelector('.tcl-hotkey-card-kb').textContent + ' → ' +
    row.querySelector('.tcl-hotkey-card-lb').textContent.toUpperCase();
  var top = row.offsetTop - body.offsetTop;
  if (top < body.scrollTop) { body.scrollTop = top; }
  else if (top + row.offsetHeight > body.scrollTop + body.clientHeight) {
    body.scrollTop = top + row.offsetHeight - body.clientHeight;
  }
  if (timer) clearTimeout(timer);
  timer = setTimeout(function () {
    if (!root.isConnected) return;
    row.className = row.className.replace(' tcl-hotkey-card-hit', '');
  }, 900);
});

