var reduce = window.matchMedia('(prefers-reduced-motion:reduce)').matches;
var pill = root.querySelector('.tcl-wizard-keys-pill');
var dots = Array.prototype.slice.call(root.querySelectorAll('.tcl-wizard-keys-dot'));
var panes = Array.prototype.slice.call(root.querySelectorAll('.tcl-wizard-keys-pane'));
var opts = Array.prototype.slice.call(root.querySelectorAll('.tcl-wizard-keys-opt'));
var accs = Array.prototype.slice.call(root.querySelectorAll('.tcl-wizard-keys-acc'));
var ft = root.querySelector('.tcl-wizard-keys-ft');
var rev = root.querySelector('.tcl-wizard-keys-rev');
var capv = root.querySelector('.tcl-wizard-keys-capv');
var fillEl = root.querySelector('.tcl-wizard-keys-fill');
var d1 = root.querySelector('.tcl-wizard-keys-d1');
var d2 = root.querySelector('.tcl-wizard-keys-d2');
var d3 = root.querySelector('.tcl-wizard-keys-d3');
var totEl = root.querySelector('.tcl-wizard-keys-tot');
var ALG = ['VWAP', 'TWAP', 'POV', 'IS', 'CLOSE'];
var WT = [45, 25, 15, 15];
var NMS = ['FUND-A CORE', 'FUND-B OPP', 'SMA-441', 'HEDGE-7'];
var QTY = 480000, PX = 214.30, ADV = 54200000, SESS = 390;
var HINTS = ['1–5 pick · ↑↓ move · ⏎ next',
  '←→ cap ±1% · ⇧←→ ±5% · ⏎ next · esc back',
  '↑↓ row · space toggle · ⏎ next · esc back',
  '⏎ stage parent · esc back'];
var st = { step: 0, algo: 0, pov: 12, cur: 0, sel: [true, true, true, true], staged: false };
function num(n, d) {
  var s = Math.abs(n).toFixed(d === undefined ? 0 : d).split('.');
  s[0] = s[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return (n < 0 ? '-' : '') + s.join('.');
}
function alloc() {
  var idx = [], tw = 0, i;
  for (i = 0; i < 4; i++) { if (st.sel[i]) { idx.push(i); tw += WT[i]; } }
  var res = [], sum = 0;
  for (i = 0; i < idx.length; i++) {
    var sh = Math.floor(QTY * WT[idx[i]] / tw);
    res.push({ i: idx[i], sh: sh, w: WT[idx[i]] / tw * 100 });
    sum += sh;
  }
  if (res.length) {
    var big = 0;
    for (i = 1; i < res.length; i++) { if (res[i].sh > res[big].sh) big = i; }
    res[big].sh += QTY - sum;
    var acc = 0;
    for (i = 0; i < res.length; i++) {
      res[i].w = Math.round(res[i].sh / QTY * 1000) / 10;
      acc += res[i].w;
    }
    res[big].w = Math.round((res[big].w + 100 - acc) * 10) / 10;
  }
  return res;
}
function line(k, v, cls) {
  var d = document.createElement('div');
  var a = document.createElement('span');
  a.className = 'tcl-wizard-keys-rk';
  a.textContent = (k + '             ').slice(0, 13);
  var b = document.createElement('span');
  b.className = cls || 'tcl-wizard-keys-rv';
  b.textContent = v;
  d.appendChild(a); d.appendChild(b);
  rev.appendChild(d);
}
function render() {
  for (var i = 0; i < dots.length; i++) {
    dots[i].className = 'tcl-wizard-keys-dot' + (i === st.step ? ' tcl-wizard-keys-at' : i < st.step ? ' tcl-wizard-keys-past' : '');
  }
  for (i = 0; i < panes.length; i++) {
    panes[i].className = 'tcl-wizard-keys-pane' + (i === st.step ? ' tcl-wizard-keys-on' + (reduce ? '' : ' tcl-wizard-keys-flash') : '');
  }
  for (i = 0; i < opts.length; i++) {
    opts[i].className = 'tcl-wizard-keys-opt' + (st.step === 0 && i === st.cur ? ' tcl-wizard-keys-cur' : '') + (i === st.algo ? ' tcl-wizard-keys-pick' : '');
  }
  var pov = st.pov / 100;
  capv.textContent = st.pov + '%';
  fillEl.style.width = ((st.pov - 5) / 20 * 100).toFixed(0) + '%';
  d1.textContent = (QTY / (ADV * pov) * SESS).toFixed(1) + ' min / ' + SESS;
  d2.textContent = (9.5 * Math.sqrt(pov)).toFixed(2) + ' bp';
  d3.textContent = num(ADV * pov) + ' sh';
  var a = alloc(), by = {};
  for (i = 0; i < a.length; i++) { by[a[i].i] = a[i]; }
  for (i = 0; i < accs.length; i++) {
    var on = st.sel[i];
    accs[i].className = 'tcl-wizard-keys-acc' + (st.step === 2 && i === st.cur ? ' tcl-wizard-keys-cur' : '') + (on ? '' : ' tcl-wizard-keys-off');
    accs[i].querySelector('.tcl-wizard-keys-box').textContent = on ? '[x]' : '[ ]';
    accs[i].querySelector('.tcl-wizard-keys-wt').textContent = on ? by[i].w.toFixed(1) + '%' : '—';
    accs[i].querySelector('.tcl-wizard-keys-sh').textContent = on ? num(by[i].sh) : '—';
  }
  totEl.textContent = num(a.length ? QTY : 0);
  while (rev.firstChild) { rev.removeChild(rev.firstChild); }
  line('ALGO', ALG[st.algo] + ' · cap ' + st.pov + '%');
  line('PARENT', num(QTY) + ' AAPL @ ' + PX.toFixed(2));
  line('NOTIONAL', num(QTY * PX, 2));
  line('EST', (QTY / (ADV * pov) * SESS).toFixed(1) + ' min · ' + (9.5 * Math.sqrt(pov)).toFixed(2) + 'bp');
  line('ACCOUNTS', a.length + ' of 4');
  for (i = 0; i < a.length; i++) {
    line(' ' + NMS[a[i].i], (num(a[i].sh) + '        ').slice(0, 9) + a[i].w.toFixed(1) + '%');
  }
  if (!st.staged) { ft.className = 'tcl-wizard-keys-ft'; ft.textContent = HINTS[st.step]; }
}
function stage() {
  st.staged = true;
  line('', '');
  line('STAGED', 'P-8841 → ' + ALG[st.algo] + ' · ' + alloc().length + ' allocs', 'tcl-wizard-keys-ok');
  ft.className = 'tcl-wizard-keys-ft tcl-wizard-keys-staged';
  ft.textContent = '✓ parent staged · R resets the wizard';
}
root.addEventListener('focus', function () { pill.textContent = 'KEYS ARMED'; });
root.addEventListener('blur', function () { pill.textContent = 'CLICK TO ARM'; });
root.addEventListener('mousedown', function () { root.focus(); });
root.addEventListener('keydown', function (e) {
  var k = e.key;
  if (k === 'Tab') return;
  if (st.staged) {
    if (k === 'r' || k === 'R') {
      e.preventDefault();
      st = { step: 0, algo: 0, pov: 12, cur: 0, sel: [true, true, true, true], staged: false };
      render();
    }
    return;
  }
  var used = true;
  if (k === 'Escape') { if (st.step > 0) { st.step--; st.cur = st.step === 0 ? st.algo : 0; } }
  else if (k === 'Enter') {
    if (st.step === 2 && !alloc().length) {
      ft.className = 'tcl-wizard-keys-ft';
      ft.textContent = '✖ select at least one account';
      e.preventDefault();
      return;
    }
    if (st.step < 3) { st.step++; st.cur = 0; } else { stage(); e.preventDefault(); return; }
  }
  else if (st.step === 0 && k >= '1' && k <= '5') { st.algo = parseInt(k, 10) - 1; st.cur = st.algo; }
  else if (st.step === 0 && (k === 'ArrowDown' || k === 'j')) { st.cur = Math.min(4, st.cur + 1); st.algo = st.cur; }
  else if (st.step === 0 && (k === 'ArrowUp' || k === 'k')) { st.cur = Math.max(0, st.cur - 1); st.algo = st.cur; }
  else if (st.step === 1 && k === 'ArrowRight') { st.pov = Math.min(25, st.pov + (e.shiftKey ? 5 : 1)); }
  else if (st.step === 1 && k === 'ArrowLeft') { st.pov = Math.max(5, st.pov - (e.shiftKey ? 5 : 1)); }
  else if (st.step === 2 && (k === 'ArrowDown' || k === 'j')) { st.cur = Math.min(3, st.cur + 1); }
  else if (st.step === 2 && (k === 'ArrowUp' || k === 'k')) { st.cur = Math.max(0, st.cur - 1); }
  else if (st.step === 2 && (k === ' ' || k === 'Spacebar')) { st.sel[st.cur] = !st.sel[st.cur]; }
  else { used = false; }
  if (used) { e.preventDefault(); render(); }
});
render();

css:
.tcl-vim-status{width:100%;max-width:360px;box-sizing:border-box;background:#05080d;border:1px solid #17222d;padding:6px 7px 0;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:9px;line-height:1.3;color:#9db1c1;outline:none;font-variant-numeric:tabular-nums}
.tcl-vim-status:focus{border-color:#3a5a7a}
.tcl-vim-status-hd{display:flex;justify-content:space-between;align-items:baseline;border-bottom:1px solid #17222d;padding-bottom:4px}
.tcl-vim-status-ttl{color:#e6eef4;font-size:8.5px;letter-spacing:.14em}
.tcl-vim-status-pill{color:#46596a;font-size:7px;letter-spacing:.1em;border:1px solid #22323f;padding:1px 4px}
.tcl-vim-status:focus .tcl-vim-status-pill{color:#6fb8ff;border-color:#3a5a7a}
.tcl-vim-status-body{max-height:104px;overflow-y:auto;overflow-x:auto;padding:3px 0;scrollbar-width:thin;scrollbar-color:#22323f transparent}
.tcl-vim-status-body::-webkit-scrollbar{width:3px;height:3px}
.tcl-vim-status-body::-webkit-scrollbar-thumb{background:#22323f}
.tcl-vim-status-body::-webkit-scrollbar-track{background:transparent}
.tcl-vim-status-row{min-width:248px;display:grid;grid-template-columns:12px 48px 8px 46px 32px 44px 24px;column-gap:5px;font-size:8.5px;padding:1px 3px;border-left:2px solid transparent}
.tcl-vim-status-row.tcl-vim-status-cur{background:#0d1720;border-left-color:#6fb8ff}
.tcl-vim-status-row.tcl-vim-status-vis{background:#161226;border-left-color:#ffbe4d}
.tcl-vim-status-ln{color:#2b3b48;text-align:right;font-size:7.5px}
.tcl-vim-status-oid{color:#5f7a8e}
.tcl-vim-status-b{color:#3ddc97}
.tcl-vim-status-s{color:#ff5c6c}
.tcl-vim-status-qt{text-align:right;color:#a9bccb}
.tcl-vim-status-sy{color:#dbe7f0}
.tcl-vim-status-px{text-align:right;color:#a9bccb}
.tcl-vim-status-tf{text-align:right;color:#4d647a;font-size:7.5px}
.tcl-vim-status-row.tcl-vim-status-edit .tcl-vim-status-px{color:#3ddc97}
.tcl-vim-status-row.tcl-vim-status-amd .tcl-vim-status-px{color:#ffbe4d}
.tcl-vim-status-row.tcl-vim-status-gone>span{color:#33434f;text-decoration:line-through}
.tcl-vim-status-caret{color:#3ddc97}
.tcl-vim-status-msg{border-top:1px solid #16212c;padding:3px 0;font-size:8px;color:#4d647a;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-height:13px}
.tcl-vim-status-msg.tcl-vim-status-err{color:#ff5c6c}
.tcl-vim-status-msg.tcl-vim-status-ok{color:#3ddc97}
.tcl-vim-status-sl{display:flex;align-items:center;gap:5px;margin:0 -7px;padding:2px 7px;background:#0c141c;border-top:1px solid #17222d;font-size:8px;letter-spacing:.04em;color:#5f7a8e;white-space:nowrap}
.tcl-vim-status-mode{background:#3a5a7a;color:#eaf4ff;padding:0 5px;letter-spacing:.12em;font-size:7.5px}
.tcl-vim-status-mode.tcl-vim-status-mi{background:#2c8f66;color:#eafff4}
.tcl-vim-status-mode.tcl-vim-status-mv{background:#8a6a1f;color:#fff6e2}
.tcl-vim-status-mode.tcl-vim-status-mc{background:#5a3f8a;color:#f2eaff}
.tcl-vim-status-buf{color:#93a9ba;min-width:0;overflow:hidden;text-overflow:ellipsis}
.tcl-vim-status-mod{color:#ffbe4d}
.tcl-vim-status-gap{flex:1}
.tcl-vim-status-rt{color:#4d647a}
.tcl-vim-status-pos{color:#93a9ba;min-width:34px;text-align:right}
.tcl-vim-status-blink{animation:tcl-vim-status-bl 1.05s steps(1,end) infinite}
@keyframes tcl-vim-status-bl{0%,50%{opacity:1}51%,100%{opacity:0}}
@media (prefers-reduced-motion:reduce){.tcl-vim-status-blink{animation:none}}

js:
var reduce = window.matchMedia('(prefers-reduced-motion:reduce)').matches;
var pill = root.querySelector('.tcl-vim-status-pill');
var body = root.querySelector('.tcl-vim-status-body');
var msg = root.querySelector('.tcl-vim-status-msg');
var modeEl = root.querySelector('.tcl-vim-status-mode');
var modEl = root.querySelector('.tcl-vim-status-mod');
var rtEl = root.querySelector('.tcl-vim-status-rt');
var posEl = root.querySelector('.tcl-vim-status-pos');
var rows = Array.prototype.slice.call(root.querySelectorAll('.tcl-vim-status-row'));
var M = rows.map(function (r) {
  var p = parseFloat(r.getAttribute('data-px'));
  return { px: p, orig: p, gone: false, tif: r.querySelector('.tcl-vim-status-tf').textContent,
    qty: parseFloat(r.querySelector('.tcl-vim-status-qt').textContent.replace(/,/g, '')) };
});
var st = { mode: 'NORMAL', cur: 0, vs: 0, buf: '', cmd: '', undo: [] };
function num(n, d) {
  var s = Math.abs(n).toFixed(d === undefined ? 0 : d).split('.');
  s[0] = s[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return (n < 0 ? '-' : '') + s.join('.');
}
function setMsg(t, cls) {
  msg.className = 'tcl-vim-status-msg' + (cls ? ' tcl-vim-status-' + cls : '');
  msg.textContent = t;
}
function range() {
  var a = Math.min(st.cur, st.vs), b = Math.max(st.cur, st.vs);
  return st.mode === 'VISUAL' ? [a, b] : [st.cur, st.cur];
}
function dirty() {
  var n = 0;
  for (var i = 0; i < M.length; i++) { if (M[i].px !== M[i].orig) n++; }
  return n;
}
function render() {
  var r = range(), live = 0, notion = 0;
  for (var i = 0; i < rows.length; i++) {
    var m = M[i], c = 'tcl-vim-status-row';
    if (st.mode === 'VISUAL' && i >= r[0] && i <= r[1]) { c += ' tcl-vim-status-vis'; }
    else if (i === st.cur) { c += ' tcl-vim-status-cur'; }
    if (m.gone) { c += ' tcl-vim-status-gone'; }
    if (st.mode === 'INSERT' && i === st.cur) { c += ' tcl-vim-status-edit'; }
    else if (m.px !== m.orig) { c += ' tcl-vim-status-amd'; }
    rows[i].className = c;
    var px = rows[i].querySelector('.tcl-vim-status-px');
    if (st.mode === 'INSERT' && i === st.cur) {
      px.textContent = st.buf;
      var car = document.createElement('span');
      car.className = 'tcl-vim-status-caret' + (reduce ? '' : ' tcl-vim-status-blink');
      car.textContent = '█';
      px.appendChild(car);
    } else { px.textContent = m.px.toFixed(2); }
    rows[i].querySelector('.tcl-vim-status-tf').textContent = m.tif;
    if (!m.gone) { live++; notion += m.qty * m.px; }
  }
  var d = dirty();
  modeEl.className = 'tcl-vim-status-mode' + (st.mode === 'INSERT' ? ' tcl-vim-status-mi' : st.mode === 'VISUAL' ? ' tcl-vim-status-mv' : st.mode === 'COMMAND' ? ' tcl-vim-status-mc' : '');
  modeEl.textContent = st.mode;
  modEl.textContent = d ? '[+' + d + ']' : '';
  rtEl.textContent = live + ' wrk · ' + (notion / 1e6).toFixed(2) + 'MM';
  posEl.textContent = (st.cur + 1) + ',1';
  if (st.mode === 'COMMAND') { setMsg(':' + st.cmd + '█'); }
  var el = rows[st.cur], top = el.offsetTop - body.offsetTop;
  if (top < body.scrollTop) { body.scrollTop = top; }
  else if (top + el.offsetHeight > body.scrollTop + body.clientHeight) {
    body.scrollTop = top + el.offsetHeight - body.clientHeight;
  }
}
function cancel(a, b) {
  var n = 0, snap = [];
  for (var i = a; i <= b; i++) { snap.push({ i: i, g: M[i].gone }); if (!M[i].gone) { M[i].gone = true; n++; } }
  st.undo.push(snap);
  setMsg(n ? 'CXL-REQ ' + n + ' order' + (n > 1 ? 's' : '') + ' · ack pending' : 'already cancelled', n ? 'ok' : 'err');
}
function ex(c) {
  c = c.trim();
  if (c === 'w' || c === 'wq') {
    var d = dirty();
    if (!d) { setMsg('no amendments to write'); }
    else {
      for (var i = 0; i < M.length; i++) { M[i].orig = M[i].px; }
      setMsg('"blotter.oms" ' + d + ' amend' + (d > 1 ? 's' : '') + ' sent · 8L', 'ok');
    }
    if (c === 'wq') { setMsg('"blotter.oms" written · session detached', 'ok'); }
  } else if (c === 'q' || c === 'q!') {
    for (var j = 0; j < M.length; j++) { M[j].px = M[j].orig; }
    setMsg('amendments discarded', 'err');
  } else if (c === 'cxl') {
    var r = range();
    cancel(r[0], r[1]);
  } else if (c.indexOf('set tif=') === 0) {
    var t = c.slice(8).toUpperCase();
    if (['DAY', 'IOC', 'GTC', 'FOK'].indexOf(t) < 0) { setMsg('E474: invalid tif ' + t, 'err'); }
    else { var rr = range(); for (var k = rr[0]; k <= rr[1]; k++) { M[k].tif = t; } setMsg('tif=' + t + ' on ' + (rr[1] - rr[0] + 1) + ' order(s)', 'ok'); }
  } else if (c === 'h' || c === 'help') {
    setMsg('j k move · i amend px · v visual · x cxl · u undo · :w');
  } else if (c === '') {
    setMsg('');
  } else {
    setMsg('E492: not an editor command: ' + c, 'err');
  }
}
root.addEventListener('focus', function () { pill.textContent = 'KEYS ARMED'; });
root.addEventListener('blur', function () { pill.textContent = 'CLICK TO ARM'; });
root.addEventListener('mousedown', function (e) {
  root.focus();
  var r = e.target;
  while (r && r !== body && r.className.indexOf('tcl-vim-status-row') < 0) { r = r.parentNode; }
  if (r && r !== body) { st.cur = rows.indexOf(r); st.mode = 'NORMAL'; render(); }
});
root.addEventListener('keydown', function (e) {
  var k = e.key;
  if (k === 'Tab') return;
  if (st.mode === 'COMMAND') {
    e.preventDefault();
    if (k === 'Escape') { st.mode = 'NORMAL'; st.cmd = ''; setMsg(''); }
    else if (k === 'Enter') { var c = st.cmd; st.mode = 'NORMAL'; st.cmd = ''; ex(c); }
    else if (k === 'Backspace') { if (!st.cmd.length) { st.mode = 'NORMAL'; setMsg(''); } else { st.cmd = st.cmd.slice(0, -1); } }
    else if (k.length === 1) { st.cmd += k; }
    render();
    return;
  }
  if (st.mode === 'INSERT') {
    e.preventDefault();
    if (k === 'Escape' || k === 'Enter') {
      var v = parseFloat(st.buf);
      if (isFinite(v) && v > 0) {
        M[st.cur].px = Math.round(v * 100) / 100;
        setMsg('limit staged ' + M[st.cur].px.toFixed(2) + ' · :w to send', 'ok');
      } else { setMsg('E521: number required after =', 'err'); }
      st.mode = 'NORMAL';
    } else if (k === 'Backspace') { st.buf = st.buf.slice(0, -1); }
    else if (/^[0-9.]$/.test(k) && st.buf.length < 8) { st.buf += k; }
    render();
    return;
  }
  var used = true;
  if (k === 'j' || k === 'ArrowDown') { st.cur = Math.min(rows.length - 1, st.cur + 1); }
  else if (k === 'k' || k === 'ArrowUp') { st.cur = Math.max(0, st.cur - 1); }
  else if (k === 'G') { st.cur = rows.length - 1; }
  else if (k === 'i') {
    if (M[st.cur].gone) { setMsg('E21: order cancelled, cannot amend', 'err'); }
    else { st.mode = 'INSERT'; st.buf = M[st.cur].px.toFixed(2); setMsg('-- INSERT -- limit price'); }
  }
  else if (k === 'v') { if (st.mode === 'VISUAL') { st.mode = 'NORMAL'; setMsg(''); } else { st.mode = 'VISUAL'; st.vs = st.cur; setMsg('-- VISUAL --'); } }
  else if (k === 'x') { var r = range(); cancel(r[0], r[1]); st.mode = 'NORMAL'; }
  else if (k === 'u') {
    if (!st.undo.length) { setMsg('already at oldest change', 'err'); }
    else { var s = st.undo.pop(); for (var i = 0; i < s.length; i++) { M[s[i].i].gone = s[i].g; } setMsg(s.length + ' change(s) restored', 'ok'); }
  }
  else if (k === ':') { st.mode = 'COMMAND'; st.cmd = ''; }
  else if (k === 'Escape') { st.mode = 'NORMAL'; setMsg(''); }
  else { used = false; }
  if (used) { e.preventDefault(); render(); }
});
render();
